    "topicNumber": "2.1.2",
    "topic": "Terminating vs non-terminating recurring forms",
    "topicName": "Terminating vs non-terminating recurring forms",
    "parentTopicName": "Properties of Rational Numbers & Decimal Representation",
    "boardCode": "MH",
    "board": "Maharashtra Board",
    "class": "9",
    "subjectCode": "MTH1",
    "subject": "Mathematics Part - 1 (Algebra)",
    "chapterNumber": 2,
    "chapter": "Real Numbers",
    "vault": "exam",
    "examCategory": "standard",
    "type": "OSC",
    "marks": 4,
    "difficulty": "medium",
    "bloomLevel": "Apply",
    "conceptTag": "Terminating Fraction 25",
    "text": "Why does the rational number \\(\\frac{13}{25}\\) have a terminating decimal form \\(0.52\\)?",
    "options": [
      {
        "text": "Because the denominator factors as \\(25 = 5^2\\), containing only prime factors 2 and/or 5",
        "isCorrect": true
      },
      {
        "text": "Because numerator 13 is a multiple of 10",
        "isCorrect": false
      },
      {
        "text": "Because denominator 25 is an odd prime number",
        "isCorrect": false
      },
      {
        "text": "Because all fractions in algebra always terminate",
        "isCorrect": false
      }
    ],
    "correctAnswer": "A",
    "solution": "1. A reduced fraction \\(\\frac{p}{q}\\) has a terminating decimal expansion if and only if \\(q = 2^m \\times 5^n\\).\n2. Here \\(25 = 25 = 5^2\\).\n3. Since only 2 and/or 5 divide the denominator, \\(\\frac{13}{25} = 0.52\\) terminates.",
