    "conceptTag": "Contradiction Proof sqrt(2)",
    "text": "In the indirect proof that \\(\\sqrt{2}\\) is irrational by contradiction, what is the initial assumption made?",
    "options": [
      {
        "text": "Assume that \\(\\sqrt{2}\\) is a rational number of the form \\(\\frac{p}{q}\\) where \\(p, q \\in \\mathbb{I}, q \\neq 0\\) and \\(\\gcd(p, q) = 1\\)",
        "isCorrect": true
      },
      {
        "text": "Assume that \\(\\sqrt{2} = 0\\)",
        "isCorrect": false
      },
      {
        "text": "Assume that \\(2\\) is a composite number",
        "isCorrect": false
      },
      {
        "text": "Assume that \\(\\sqrt{2}\\) is a negative integer",
        "isCorrect": false
      }
    ],
    "correctAnswer": "A",
    "solution": "1. In proof by contradiction (reductio ad absurdum), we assume the exact negation of the proposition to be proved.\n2. To prove \\(\\sqrt{2}\\) is irrational, we assume \\(\\sqrt{2}\\) is rational (in simplest co-prime form \\(p/q\\)).\n3. Deriving a contradiction to \\(\\gcd(p, q) = 1\\) proves \\(\\sqrt{2}\\) is irrational.",
    "timesUsed": 0,
