    "correctAnswer": "D",
    "solution": "1. Simplify each surd: \\(\\sqrt{18} = 3\\sqrt{2}\\) and \\(\\sqrt{50} = 5\\sqrt{2}\\).\n2. Two surds are like surds if their order is equal and their radicands in simplest form are equal.\n3. Both have order 2 and common radical factor \\(\\sqrt{2}\\), so they are like surds.",
